mkdir -p /tmp/mc-base-check && cat > /tmp/mc-base-check/base-test.mjs <<'EOF'
import * as base from "/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/midcentury-crew2/vocab/base.mjs";
import { readFileSync } from "node:fs";
const pal = JSON.parse(readFileSync("/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/midcentury-crew2/palette.json", "utf8"));
const ids = new Set([...Object.values(pal.roles).flat(), ...pal.objects]);
let bad = [], n = 0;
for (const [k, v] of Object.entries(base)) if (typeof v === "string" && /^[a-z_]+$/.test(v)) { n++; if (!ids.has(v)) bad.push(`${k}=${v}`); }
console.log(`block constants checked: ${n}; not in palette: ${bad.length ? bad.join(", ") : "none"}`);
const a = base.rng(7), b = base.rng(7), c = base.rng(8);
const sa = [a(), a(), a()], sb = [b(), b(), b()];
const inRange = sa.every((v) => v >= 0 && v < 1);
console.log(`rng same seed same: ${JSON.stringify(sa) === JSON.stringify(sb)}; different seed differs: ${c() !== sa[0]}; in [0,1): ${inRange}`);
console.log(`pool inPool(29,14)=${base.inPool(29,14)} inPool(29,13)=${base.inPool(29,13)} SIZE=${base.SIZE}`);
EOF
node /tmp/mc-base-check/base-test.mjs

